<?php
/** Artdon Lighting Resources Videos */
declare(strict_types=1);
require_once __DIR__ . '/includes/public_cache.php';
web_public_cache_start('resources-videos', 900);
require_once __DIR__ . '/includes/bootstrap.php';
require_once __DIR__ . '/includes/artdon_pages_v710.php';
require_once __DIR__ . '/includes/schema.php';
require_once __DIR__ . '/includes/resources_video_data.php';
require_once __DIR__ . '/includes/resources_page_data.php';

$content = artdon_v710_content();
$site = is_array($content['site'] ?? null) ? $content['site'] : (function_exists('web_get_block') ? (array)web_get_block('site') : []);
$siteUrl = artdon_v710_site_url($site);
$company = trim((string)($site['company'] ?? 'Artdon Lighting Limited')) ?: 'Artdon Lighting Limited';
$canonical = $siteUrl . '/resources-videos.php';
$resourcePage = [];
$videos = [];
$videoDbAvailable = false;
try {
    $error = null;
    $pdo = web_db($error);
    if ($pdo) { $videoDbAvailable = true; web_migrate($pdo); $resourcePage = artdon_resource_page_get($pdo, 'videos'); $videos = artdon_resource_video_items($pdo, true); }
} catch (Throwable $ignored) {}
$pageTitle = trim((string)($resourcePage['seo_title'] ?? '')) ?: 'Videos | Artdon Lighting Resources';
$pageDescription = trim((string)($resourcePage['seo_description'] ?? '')) ?: 'Explore product showcases, installation guides, expert insights and more.';
$seoKeywords = trim((string)($resourcePage['seo_keywords'] ?? ''));
$heroImage = trim((string)($resourcePage['hero_image'] ?? '')) ?: 'assets/img/hero/hero-technical-downloads.webp';
$heroAlt = trim((string)($resourcePage['hero_image_alt'] ?? '')) ?: 'Artdon video resources';
$heroTitle = trim((string)($resourcePage['hero_title'] ?? 'Videos')) ?: 'Videos';
$heroDescription = trim((string)($resourcePage['hero_description'] ?? '')) ?: 'Explore product showcases, installation guides, expert insights and more.';
$pageContent = is_array($resourcePage['content'] ?? null) ? $resourcePage['content'] : [];
if (!$videoDbAvailable && !$videos) {
    foreach (artdon_resource_video_default_items() as $i => $item) $videos[] = $item + ['id'=>$i+1,'main_label'=>artdon_resource_video_main_categories()[$item['main_category']] ?? 'Product Videos','sub_label'=>artdon_resource_video_sub_categories()[$item['sub_category']] ?? 'All Products','cover_alt'=>$item['title'],'is_active'=>true];
}
$mainCats = artdon_resource_video_main_categories();
$subCats = artdon_resource_video_sub_categories();
$productSubCats = $subCats;
$counts = array_fill_keys(array_keys($mainCats), 0);
foreach ($videos as $video) if (isset($counts[$video['main_category']])) $counts[$video['main_category']]++;
$videoSchemaNodes = [];
foreach (array_slice($videos, 0, 30) as $videoIndex => $video) {
    $videoSchemaNodes[] = artdon_schema_video($video, $canonical, $siteUrl, $videoIndex + 1);
}
$schema = artdon_schema_graph(array_merge([
    artdon_schema_organization($site, $siteUrl),
    artdon_schema_website($site, $siteUrl),
    artdon_schema_webpage($canonical, $pageTitle, $pageDescription, $siteUrl, 'CollectionPage'),
    artdon_schema_breadcrumb([
        ['name'=>'Home','url'=>'/'],
        ['name'=>'Resources','url'=>'/resources.php'],
        ['name'=>'Videos','url'=>'/resources-videos.php'],
    ], $siteUrl),
], $videoSchemaNodes));
function rv_icon(string $key): string
{
    $svg='width="34" height="34" viewBox="0 0 34 34" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"';
    return match($key){
        'install'=>'<svg '.$svg.'><path d="m21 5 8 8-4 4-3-3-8 8v4l-6 3-3-3 3-6h4l8-8-3-3 4-4Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg>',
        'knowledge'=>'<svg '.$svg.'><path d="M8 5h13l5 5v19H8V5Z" stroke="currentColor" stroke-width="1.7"/><path d="M21 5v6h6M12 17h10M12 22h10M12 27h6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>',
        'other'=>'<svg '.$svg.'><rect x="5" y="8" width="24" height="18" rx="2" stroke="currentColor" stroke-width="1.7"/><path d="m15 14 8 3-8 3v-6Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg>',
        default=>'<svg '.$svg.'><rect x="5" y="8" width="24" height="18" rx="2" stroke="currentColor" stroke-width="1.7"/><path d="M11 26v3M23 26v3M14 14h7M14 18h5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>',
    };
}
