<script>
document.addEventListener('DOMContentLoaded',function(){var cards=[].slice.call(document.querySelectorAll('[data-video-card]')),stats=[].slice.call(document.querySelectorAll('.rv-stat[data-main]')),tags=[].slice.call(document.querySelectorAll('.rv-tag[data-sub]')),search=document.getElementById('videoSearch'),sort=document.getElementById('videoSort'),grid=document.getElementById('videoGrid'),load=document.getElementById('videoLoad'),wrap=document.getElementById('videoLoadWrap'),empty=document.getElementById('videoEmpty'),title=document.getElementById('videoSectionTitle'),desc=document.getElementById('videoSectionDesc'),listTitle=document.getElementById('videoListTitle'),tagBar=document.getElementById('productSubcategoryBar'),limit=8,main='product',sub='all-products';var labels={product:'Product Videos',install:'Install Videos',knowledge:'Knowledge Videos',other:'Other Videos'},shortLabels={product:'Product',install:'Install',knowledge:'Knowledge',other:'Other'},descs={product:<?= json_encode((string)($pageContent['product_description'] ?? 'Explore our product series and find the right lighting solution for your project.'), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>,install:<?= json_encode((string)($pageContent['install_description'] ?? 'Watch installation guides and setup notes for Artdon lighting systems.'), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>,knowledge:<?= json_encode((string)($pageContent['knowledge_description'] ?? 'Learn lighting knowledge, specification tips and expert insights.'), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>,other:<?= json_encode((string)($pageContent['other_description'] ?? 'Browse other Artdon videos and company resources.'), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>};function apply(){var q=(search&&search.value||'').toLowerCase().trim(),isProduct=main==='product',items=cards.filter(function(c){return c.dataset.main===main&&(!isProduct||sub==='all-products'||c.dataset.sub===sub)&&(!q||(c.dataset.title+' '+c.dataset.desc).indexOf(q)>-1);});items.sort(function(a,b){var s=sort&&sort.value||'newest';if(s==='title')return a.dataset.title.localeCompare(b.dataset.title);if(s==='popular')return (b.dataset.popular||'0').localeCompare(a.dataset.popular||'0');return s==='oldest'?String(a.dataset.date).localeCompare(String(b.dataset.date)):String(b.dataset.date).localeCompare(String(a.dataset.date));});items.forEach(function(c){grid.appendChild(c);});cards.forEach(function(c){c.hidden=true;});items.forEach(function(c,i){c.hidden=i>=limit;});if(tagBar)tagBar.hidden=!isProduct;if(title)title.textContent=labels[main]||'Product Videos';if(desc)desc.textContent=descs[main]||'';if(listTitle){var activeTag=document.querySelector('.rv-tag[data-sub="'+sub+'"]'),prefix=isProduct?(sub==='all-products'?'All ':((activeTag&&activeTag.textContent)||'')+' '):'All ';listTitle.textContent=prefix+(isProduct?(labels[main]||'Product Videos'):((shortLabels[main]||labels[main]||'Video')+' Videos'))+' ('+items.length+')';}if(empty)empty.hidden=items.length!==0;if(wrap)wrap.hidden=items.length<=limit;}function embedUrl(url,source){url=String(url||'').trim();source=String(source||'').toLowerCase();if(!url)return '';if(/\.(mp4|webm|mov)($|\?)/i.test(url))return url;var m;if(source==='youtube'||/youtu\.be|youtube\.com/i.test(url)){m=url.match(/youtu\.be\/([^?&#]+)/i)||url.match(/[?&]v=([^?&#]+)/i)||url.match(/youtube\.com\/embed\/([^?&#]+)/i)||url.match(/youtube\.com\/shorts\/([^?&#]+)/i);return m&&m[1]?'https://www.youtube.com/embed/'+m[1].replace(/[^A-Za-z0-9_-]/g,''):url;}if(source==='vimeo'||/vimeo\.com/i.test(url)){if(/player\.vimeo\.com/i.test(url))return url;m=url.match(/vimeo\.com\/(?:video\/)?(\d+)/i);return m&&m[1]?'https://player.vimeo.com/video/'+m[1]:url;}return url;}stats.forEach(function(b){b.addEventListener('click',function(){main=b.dataset.main;limit=8;stats.forEach(function(x){x.classList.toggle('is-active',x===b);});apply();});});tags.forEach(function(b){b.addEventListener('click',function(){sub=b.dataset.sub;limit=8;tags.forEach(function(x){x.classList.toggle('is-active',x===b);});apply();});});if(search)search.addEventListener('input',function(){limit=8;apply();});if(sort)sort.addEventListener('change',apply);if(load)load.addEventListener('click',function(){limit+=8;apply();});var modal=document.getElementById('videoModal'),player=document.getElementById('videoPlayer');document.addEventListener('click',function(e){var c=e.target.closest&&e.target.closest('[data-video-card]');if(c){var url=embedUrl(c.dataset.video||'',c.dataset.source||'');if(!url)return;player.innerHTML=c.dataset.source==='local'||/\.(mp4|webm|mov)($|\?)/i.test(url)?'<video src="'+url+'" controls autoplay></video>':'<iframe src="'+url+'" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>';modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');return;}if(e.target.closest&&e.target.closest('[data-video-close]')){modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');player.innerHTML='';}});apply();});
</script></body></html>
